/* Advanced academy tracks + glossary (English) for /where-to-start/.
   The 12-lesson "Basics" track stays in build/data/wts-i18n.js (translated). These deeper tracks are English-first
   (translation is a follow-up). Schema per lesson: {id,t,mins,sum,body:[{h?,p}],key:[],ex?,quiz:{q,o,a},link?{href,label}}. */

const FUNDAMENTALS = {
  "id": "fundamentals",
  "name": "Trading Fundamentals",
  "icon": "📊",
  "blurb": "How crypto futures actually work — leverage, margin, liquidation, orders, funding.",
  "level": "core",
  "lessons": [
    { "id": "what-is-a-perp", "t": "What is a perpetual futures contract?", "mins": 4, "sum": "Perps let you trade price without owning the coin — and they never expire.", "body": [ { "h": "Spot vs futures", "p": "When you buy crypto on the <b>spot</b> market, you own the actual coin — buy 1 BTC and it sits in your wallet. A <b>futures contract</b> is different: it's an agreement whose value tracks the price of an asset, but you never have to hold the asset itself. You're trading the <i>price movement</i>, not the coin. Profit or loss is settled in cash (usually a stablecoin like USDT)." }, { "h": "What makes it 'perpetual'", "p": "Traditional futures have an <b>expiry date</b> — a day when the contract settles and closes. A <b>perpetual futures contract</b> (a \"perp\") removes that expiry. You can hold the position for an hour or a year. To keep the perp's price glued to the real spot price even without an expiry, exchanges use a small recurring payment between traders called the <b>funding rate</b> (covered in a later lesson)." }, { "h": "Why traders use perps", "p": "Perps add two things spot can't easily offer: you can profit when price goes <b>down</b> (by going \"short\"), and you can control a larger position with less cash using <b>leverage</b>. That flexibility is powerful — and it's also why perps carry far more risk than simply buying and holding. Treat them as a tool to understand thoroughly before risking real money." } ], "key": [ "Spot = you own the coin; futures = you trade its price without owning it.", "Perpetual contracts never expire — no settlement date to worry about.", "The funding rate keeps a perp's price tracking the real spot price.", "Perps allow shorting and leverage, which adds both opportunity and risk." ], "ex": "You think BTC will rise but don't want to buy and store actual Bitcoin. Instead you open a BTC perpetual position. If BTC moves from <code>$60,000</code> to <code>$63,000</code> (+5%), your position gains roughly 5% of its size in USDT — and you never held a single satoshi. If BTC had fallen 5%, you'd have lost that amount instead.", "quiz": { "q": "What is the key difference between a perpetual future and a traditional future?", "o": [ "A perpetual future has no expiry date", "A perpetual future cannot use leverage", "A perpetual future requires owning the underlying coin", "A perpetual future can only be bought, never sold short" ], "a": 0 }, "link": { "href": "/paper-trade", "label": "Try a risk-free paper trade" } },
    { "id": "long-vs-short", "t": "Long vs Short", "mins": 4, "sum": "Go long to profit when price rises, short to profit when it falls.", "body": [ { "h": "Going long", "p": "Going <b>long</b> means you're betting the price will <i>rise</i>. You open the position at one price and profit if price climbs above it. This is the familiar direction — it's effectively the same bet as buying a coin on spot, just done through a futures contract. If you go long at $100 and price hits $110, you're in profit." }, { "h": "Going short", "p": "Going <b>short</b> means you're betting the price will <i>fall</i>. Mechanically, the exchange lets you sell the contract first at today's price and buy it back later at a (hopefully lower) price, keeping the difference. You profit when price <i>drops</i> below your entry. Shorting is what makes futures special — on plain spot you can only profit when things go up." }, { "h": "Same risks, opposite directions", "p": "Both directions can win or lose; neither is 'safer.' A long loses if price falls; a short loses if price rises. One important asymmetry: a long can only fall to zero (-100%), but a short's losses are theoretically unlimited because price can keep rising with no ceiling. Always know which direction you're in and where your position stops working." } ], "key": [ "Long = profit when price goes up; you buy first, sell later.", "Short = profit when price goes down; you sell first, buy back later.", "Shorting is the futures superpower — you can profit in falling markets.", "A short's potential loss is unbounded since price has no upper limit." ], "ex": "<b>Long:</b> You go long ETH at <code>$3,000</code>. Price rises to <code>$3,300</code> — you gain <code>$300</code> per ETH of position. <br><b>Short:</b> You short ETH at <code>$3,000</code>. Price falls to <code>$2,700</code> — you gain <code>$300</code> per ETH. But if price instead rose to <code>$3,300</code>, the short would <i>lose</i> <code>$300</code>.", "quiz": { "q": "You open a short position on BTC at $60,000. You make a profit if BTC...", "o": [ "rises to $65,000", "falls to $55,000", "stays exactly at $60,000", "is delisted from the exchange" ], "a": 1 }, "link": { "href": "/guides/long-vs-short-crypto/", "label": "Read the full long vs short guide" } },
    { "id": "leverage-explained", "t": "Leverage explained", "mins": 5, "sum": "Leverage multiplies your position size — and your gains and losses equally.", "body": [ { "h": "What leverage is", "p": "<b>Leverage</b> lets you open a position larger than your own cash by effectively borrowing the rest from the exchange. With <b>10x leverage</b>, $100 of your money controls a $1,000 position. The $100 you put up is called your <b>margin</b>; the full $1,000 is the <b>notional</b> (the total position value). Leverage is written as a multiplier: 2x, 5x, 10x, 50x, and so on." }, { "h": "It cuts both ways", "p": "Here's the part beginners underestimate: leverage multiplies <i>both</i> directions. At 10x, a 1% move in your favor is a <b>+10%</b> gain on your margin — but a 1% move against you is a <b>-10%</b> loss. The bigger the leverage, the smaller the price move needed to double your money <i>or</i> wipe it out. Leverage doesn't change the odds; it changes the stakes." }, { "h": "Why high leverage is dangerous", "p": "At 10x, roughly a 10% adverse move can erase your entire margin (your position gets <b>liquidated</b> — next lesson). At 50x, just a ~2% move does it. Crypto routinely swings several percent in minutes, so high leverage means tiny, normal wiggles can end your trade. Most experienced traders use modest leverage precisely to survive that noise." } ], "key": [ "Leverage = controlling a bigger position with less cash (your margin).", "10x means $100 controls $1,000 — and a 1% move = 10% of your margin.", "Gains AND losses are magnified by the same multiplier.", "Higher leverage = a smaller adverse move wipes you out." ], "ex": "You put up <code>$100</code> margin at <code>10x</code>, opening a <code>$1,000</code> long. <br>• Price rises 5% → position gains <code>$50</code> = <b>+50%</b> on your margin. <br>• Price falls 5% → position loses <code>$50</code> = <b>-50%</b> on your margin. <br>• Price falls ~10% → you lose your whole <code>$100</code> and get liquidated.", "quiz": { "q": "With 10x leverage, if the price moves 2% against your position, your margin changes by about...", "o": [ "-2%", "-10%", "-20%", "0%, leverage doesn't affect losses" ], "a": 2 }, "link": { "href": "/guides/what-is-leverage-in-crypto/", "label": "Learn leverage in depth" } },
    { "id": "margin-modes", "t": "Margin: isolated vs cross", "mins": 5, "sum": "Margin is your collateral — and isolated vs cross decides how much is at risk.", "body": [ { "h": "Initial vs maintenance margin", "p": "<b>Margin</b> is the collateral you post to open and hold a position. The <b>initial margin</b> is what you need to <i>open</i> the trade (e.g. $100 to open a $1,000 position at 10x). The <b>maintenance margin</b> is the minimum equity you must keep for the position to stay open. If your losses eat into your margin and it drops to the maintenance level, the position gets liquidated." }, { "h": "Isolated margin", "p": "In <b>isolated margin</b> mode, only the margin you assigned to that one position is at risk. If the trade gets liquidated, you lose <i>just</i> that allocated amount — the rest of your account balance is untouched. This caps your downside per trade, which is why many traders prefer it. The tradeoff: the position is liquidated sooner because it can't pull from spare account funds." }, { "h": "Cross margin", "p": "In <b>cross margin</b> mode, your entire available account balance backs the position. That gives the trade more cushion before liquidation — but if it goes badly, it can drain funds from across your account, potentially taking other positions down with it. Cross can survive bigger swings, yet it puts much more at stake. Beginners usually start with isolated to keep losses contained." } ], "key": [ "Initial margin opens the trade; maintenance margin keeps it open.", "Isolated: only the assigned margin is at risk — losses are capped per trade.", "Cross: your whole balance backs the trade — more cushion, but more exposure.", "Isolated liquidates sooner; cross can drain the account if it goes wrong." ], "ex": "You have <code>$1,000</code> in your account and open a trade with <code>$100</code> margin. <br><b>Isolated:</b> worst case you lose that <code>$100</code>; the other <code>$900</code> is safe. <br><b>Cross:</b> the position can draw on the full <code>$1,000</code> to avoid liquidation — it survives a bigger move, but a very bad trade could cost far more than <code>$100</code>.", "quiz": { "q": "In isolated margin mode, what is the most you can lose on a single position?", "o": [ "Your entire account balance", "Only the margin you allocated to that position", "Nothing — isolated positions can't be liquidated", "Twice the initial margin" ], "a": 1 }, "link": { "href": "/calculators?c=liq", "label": "Estimate your liquidation price" } },
    { "id": "liquidation", "t": "Liquidation — how you get wiped out", "mins": 5, "sum": "When losses eat your margin to the maintenance level, the exchange closes you out.", "body": [ { "h": "What liquidation is", "p": "<b>Liquidation</b> is the exchange forcibly closing your position because your losses have consumed almost all your margin. It happens when your equity falls to the <b>maintenance margin</b> — the minimum required to keep the trade open. The exchange does this to make sure you don't lose more than you put up (in isolated mode). When liquidated, you typically lose most or all of the margin on that position." }, { "h": "The liquidation price", "p": "Every leveraged position has a <b>liquidation price</b> — the price level at which it gets closed. For a long, it's below your entry; for a short, it's above. The key insight: <b>higher leverage moves the liquidation price closer to your entry</b>. A 2x long can fall ~50% before liquidating; a 10x long only ~10%; a 50x long only ~2%. More leverage = less room for the price to breathe." }, { "h": "Why it's so easy to underestimate", "p": "Beginners often think 'the trade just has to go my way eventually.' But with high leverage, a normal intraday wiggle can hit your liquidation price first — and once liquidated, you're out, even if price later moves exactly where you predicted. Knowing your liquidation price <i>before</i> you enter is one of the most important habits in leveraged trading." } ], "key": [ "Liquidation = forced closure when equity hits the maintenance margin.", "Each position has a liquidation price; longs liquidate below entry, shorts above.", "Higher leverage pulls the liquidation price closer to your entry.", "Once liquidated you're out — even if price later goes your way." ], "ex": "You open a <code>10x</code> long on BTC at <code>$60,000</code> with <code>$100</code> margin (a <code>$1,000</code> = 0.01667 BTC notional). Roughly a 10% drop wipes your margin, so your liquidation price sits near <code>$54,000</code> (a bit higher once the maintenance margin and fees are counted). If instead you'd used <code>2x</code>, BTC would need to fall to about <code>$30,000</code> — a ~50% drop — to liquidate. Same coin, same entry: leverage alone moved the danger zone from −50% to −10%.", "quiz": { "q": "You go long with higher leverage. What happens to your liquidation price?", "o": [ "It moves further from your entry, giving more room", "It moves closer to your entry, giving less room", "It disappears — high leverage removes liquidation", "It only matters for short positions" ], "a": 1 }, "link": { "href": "/calculators?c=liq", "label": "Calculate your liquidation price" } },
    { "id": "order-types", "t": "Order types: market, limit, stop", "mins": 5, "sum": "Market fills now, limit waits for your price, stop triggers when a level is hit.", "body": [ { "h": "Market order", "p": "A <b>market order</b> executes <i>immediately</i> at the best available price. You get filled right away — the upside is speed and certainty of execution. The downside is <b>slippage</b>: in fast or thin markets, the price you actually get can be a little worse than the price you saw, because your order eats through the nearest available orders. Use market orders when getting in or out <i>now</i> matters more than the exact price." }, { "h": "Limit order", "p": "A <b>limit order</b> lets you set the exact price you're willing to trade at, and it only fills at that price or better. Want to buy ETH at $2,950 when it's currently $3,000? A limit order waits until price drops to $2,950. The benefit is price control and no slippage; the catch is it might <i>never fill</i> if price doesn't reach your level. Limit orders are how you trade patiently instead of chasing." }, { "h": "Stop order", "p": "A <b>stop order</b> sits dormant until price hits a trigger level, then activates. Its most important use is the <b>stop-loss</b>: an order that closes your position once price moves against you by a set amount, capping your loss automatically. For example, a stop-loss on a long triggers a sell if price falls to your chosen level. Stops are your safety net — they enforce your exit even when you're not watching." } ], "key": [ "Market = instant fill at current price, but risks slippage.", "Limit = fills only at your chosen price or better, may never fill.", "Stop = triggers an order when price hits a level — basis of the stop-loss.", "Slippage is the gap between expected and actual fill price in fast markets." ], "ex": "ETH is at <code>$3,000</code>. <br>• <b>Market buy:</b> fills immediately near <code>$3,000</code> (maybe <code>$3,001</code> after slippage). <br>• <b>Limit buy at $2,950:</b> waits and only fills if price drops to <code>$2,950</code> or lower. <br>• <b>Stop-loss at $2,850</b> on your long: does nothing until price falls to <code>$2,850</code>, then sells to cap your loss.", "quiz": { "q": "Which order guarantees the price but NOT that it will actually fill?", "o": [ "Market order", "Limit order", "Stop-loss order", "All orders always fill" ], "a": 1 } },
    { "id": "funding-rate", "t": "Funding rate", "mins": 5, "sum": "Small periodic payments between longs and shorts keep perps tied to spot price.", "body": [ { "h": "The problem funding solves", "p": "A perpetual future has no expiry, so nothing naturally forces its price to match the real <b>spot</b> price. Without a fix, the perp could drift far from the actual market. The <b>funding rate</b> is the mechanism that tethers them: it's a small recurring payment exchanged <i>directly between traders</i> (not paid to the exchange), usually every 8 hours." }, { "h": "Who pays whom", "p": "The direction depends on whether the perp is trading above or below spot. When the perp trades <i>above</i> spot (more demand from longs), funding is <b>positive</b> and <b>longs pay shorts</b>. When the perp trades <i>below</i> spot (more demand from shorts), funding is <b>negative</b> and <b>shorts pay longs</b>. This payment nudges traders toward the cheaper side, pulling the perp price back in line with spot." }, { "h": "Why it matters to you", "p": "Funding is charged on your full <b>notional</b> position size, not just your margin — so with leverage it can add up. If you hold a leveraged long while funding is strongly positive, you pay a fee every funding period just to keep the position open, which quietly eats your profits. On the flip side, you can sometimes <i>earn</i> funding by holding the less-crowded side. Always check the funding rate before holding a position for a long time." } ], "key": [ "Funding keeps the perpetual's price anchored to the spot price.", "Positive funding: longs pay shorts. Negative funding: shorts pay longs.", "It's paid between traders (often every 8h), not to the exchange.", "It's charged on notional, so leverage magnifies the cost or income." ], "ex": "You hold a <code>$10,000</code> notional long while the funding rate is <code>+0.01%</code> per 8 hours. Each funding period you pay <code>$10,000 × 0.0001 = $1</code> to the shorts — about <code>$3/day</code>. It sounds tiny, but on a heavily leveraged position held for weeks during high funding, these payments can quietly erode a meaningful chunk of your margin.", "quiz": { "q": "The funding rate is positive. What does that mean?", "o": [ "The exchange pays all traders a bonus", "Longs pay shorts to keep the perp tied to spot", "Shorts pay longs to keep the perp tied to spot", "Funding is only charged when you get liquidated" ], "a": 1 }, "link": { "href": "/funding/", "label": "Check live funding rates" } },
    { "id": "pnl-roe-notional", "t": "P&L, ROE and notional", "mins": 5, "sum": "Notional is your position size; P&L is dollars gained; ROE is the % on your margin.", "body": [ { "h": "Notional vs margin", "p": "Your <b>notional</b> is the full size of your position — margin multiplied by leverage. Put up $200 at 5x and your notional is $1,000. Your <b>margin</b> is the actual cash you risked ($200). Keep these separate in your head: price moves act on the <i>notional</i>, but the percentage return you feel is measured against your <i>margin</i>." }, { "h": "How P&L is computed", "p": "<b>P&L</b> (profit and loss) is your gain or loss in dollars. For a long: <code>P&L = (exit price − entry price) × position size in coins</code>. For a short, it's reversed: <code>(entry − exit) × size</code>. The dollar P&L depends on the notional, not on how much margin you posted — leverage doesn't change the dollar profit of a given position size, only how much of your <i>own</i> cash was tied up to get it." }, { "h": "ROE: the percentage that bites", "p": "<b>ROE</b> (return on equity) is your P&L as a percentage of your <i>margin</i>: <code>ROE = P&L ÷ margin × 100</code>. This is where leverage shows up. A 5% move on the notional becomes a 25% ROE at 5x leverage, because your margin was one-fifth of the position. ROE is the number that feels real in your account — and it's why a small price move can mean a huge percentage swing on leveraged trades." } ], "key": [ "Notional = margin × leverage = your true position size.", "P&L (dollars) depends on notional and price change, not on leverage.", "ROE = P&L ÷ margin — this is where leverage magnifies the percentage.", "Same dollar P&L is a bigger ROE the less margin you posted." ], "ex": "You long with <code>$200</code> margin at <code>5x</code> → <code>$1,000</code> notional. Entry <code>$50</code>, you hold 20 coins (<code>$1,000 ÷ $50</code>). Price rises to <code>$52.50</code> (+5%). <br>• <b>P&L</b> = <code>($52.50 − $50) × 20 = $50</code>. <br>• <b>ROE</b> = <code>$50 ÷ $200 = +25%</code>. A 5% price move became a 25% return because of the 5x leverage.", "quiz": { "q": "You have $200 margin at 5x. The price moves 5% in your favor. What's your approximate ROE?", "o": [ "5%", "10%", "25%", "1%" ], "a": 2 }, "link": { "href": "/calculators?c=pnl", "label": "Calculate your P&L and ROE" } },
    { "id": "position-sizing", "t": "Position sizing & risk-reward", "mins": 6, "sum": "Size each trade by the dollars you'll risk, not by leverage — and demand good R:R.", "body": [ { "h": "Size by risk, not by leverage", "p": "The single most important habit in trading is deciding how much you'll <i>lose</i> if you're wrong — <i>before</i> you enter. A common rule is to risk only a small fixed percentage of your account per trade, often <b>1–2%</b>. Notice this has nothing to do with leverage: leverage just determines how much margin you post, but your real risk is the distance from your entry to your <b>stop-loss</b>, times your position size." }, { "h": "Calculating position size", "p": "Work backwards from your risk. <b>Position size = dollars you'll risk ÷ distance to your stop-loss (as a fraction).</b> First pick your dollar risk (e.g. 1% of a $5,000 account = $50). Then set where your stop-loss goes based on the chart. The gap between entry and stop, combined with that $50, tells you exactly how big the position should be. This keeps a single bad trade from doing real damage." }, { "h": "Risk-reward ratio", "p": "The <b>risk-reward ratio (R:R)</b> compares what you're risking to what you aim to gain. If you risk $50 to make $150, that's a <b>1:3</b> R:R. Good R:R is what lets you be profitable even when you're wrong often: at 1:3, you only need to win about 1 in 4 trades to break even. Chasing trades with bad R:R (risking a lot to make a little) is how accounts bleed out even with a high win rate." } ], "key": [ "Decide your dollar loss before entering — risk a small % (e.g. 1–2%) per trade.", "Position size = risk dollars ÷ distance to your stop-loss.", "R:R compares risk to reward; aim for setups where reward outweighs risk.", "Good R:R lets you profit even with a modest win rate." ], "ex": "Account: <code>$5,000</code>. You risk <code>1%</code> = <code>$50</code> per trade. You enter a long at <code>$100</code> with a stop-loss at <code>$95</code> (a <code>5%</code> = $5 gap). <br>• <b>Position size</b> = <code>$50 ÷ $5 = 10 coins</code> (<code>$1,000</code> notional). <br>• If your target is <code>$115</code>, you'd gain <code>$15 × 10 = $150</code> vs <code>$50</code> risked → a <b>1:3</b> R:R. Hit your stop and you lose exactly the <code>$50</code> you planned for.", "quiz": { "q": "You risk $50 on a trade aiming to make $150. What is your risk-reward ratio?", "o": [ "1:1", "3:1 against you", "1:3", "1:5" ], "a": 2 }, "link": { "href": "/calculators?c=size", "label": "Calculate your position size" } }
  ]
};

const INDICATORS = {
  "id": "indicators",
  "name": "Indicators & Technical Analysis",
  "icon": "📈",
  "blurb": "Read price like a pro — candles, trend, moving averages, RSI, MACD, Bollinger and more.",
  "level": "advanced",
  "lessons": [
    { "id": "read-candlestick", "t": "How to read a candlestick", "mins": 4, "sum": "Open, high, low, close — and what the body and wicks tell you.", "body": [ { "h": "The four prices in one candle", "p": "Every candlestick packs four numbers for a time period (1m, 1h, 1 day, etc.): the <b>open</b> (first traded price), the <b>close</b> (last traded price), the <b>high</b> (highest price reached), and the <b>low</b> (lowest). One candle = one period; a 4h chart draws a new candle every 4 hours." }, { "h": "Body vs wick", "p": "The thick rectangle is the <b>body</b> — it spans from open to close. The thin lines above and below are the <b>wicks</b> (or shadows), marking the high and low. A long upper wick means price pushed up but got rejected and fell back; a long lower wick means sellers pushed down but buyers bought it back up." }, { "h": "Bullish vs bearish", "p": "If the close is <i>above</i> the open, the candle is <b>bullish</b> (price rose over the period) — usually drawn green or hollow. If the close is <i>below</i> the open, it's <b>bearish</b> (price fell) — usually red or filled. A small body with long wicks shows indecision; a big body with tiny wicks shows strong one-sided pressure." } ], "key": [ "A candle shows open, high, low and close for one time period.", "Body = open-to-close range; wicks = the extremes (high and low).", "Close above open = bullish (green); close below open = bearish (red).", "Long wicks signal rejection; big bodies signal conviction." ], "ex": "A green candle opens at $100 and closes at $108, with a high of $110 and a low of $99. The body covers $100–$108; the short upper wick ($108→$110) shows a brief push above the close that didn't hold.", "quiz": { "q": "A candle's close is below its open. What does that tell you?", "o": [ "Price rose over the period (bullish)", "Price fell over the period (bearish)", "There was no trading", "The high equals the low" ], "a": 1 }, "link": { "href": "/charts", "label": "Try it on the chart workspace" } },
    { "id": "trend-support-resistance", "t": "Trend, support & resistance", "mins": 5, "sum": "Higher highs/lows define trend; S/R levels are where price reacts.", "body": [ { "h": "What a trend looks like", "p": "An <b>uptrend</b> is a staircase of <i>higher highs</i> and <i>higher lows</i> — each rally peaks higher and each pullback bottoms higher than the last. A <b>downtrend</b> is the opposite: <i>lower highs</i> and <i>lower lows</i>. When highs and lows are flat, price is <b>ranging</b> (sideways). The trend is just the prevailing direction — it can change, so it's a context, not a promise." }, { "h": "Support and resistance", "p": "<b>Support</b> is a price area where buyers have repeatedly stepped in and stopped price falling (a floor). <b>Resistance</b> is where sellers repeatedly capped a rally (a ceiling). They're <i>zones</i>, not exact lines, and they form because traders remember those prices. A level that's been touched several times is considered stronger." }, { "h": "Breakouts and flips", "p": "A <b>breakout</b> is when price closes decisively through a level. Watch for <b>fakeouts</b> (false breakouts): price pokes through, then snaps back — very common. A useful clue is a <i>retest</i>: after breaking resistance, price often returns to it, and old resistance can act as new support (a 'flip'). Pivot Points are a formula-based way to auto-plot likely S/R for the day." } ], "key": [ "Uptrend = higher highs + higher lows; downtrend = lower highs + lower lows.", "Support is a buying floor; resistance is a selling ceiling — both are zones.", "Breakouts can be fake; a successful retest adds confidence.", "Broken resistance often becomes new support, and vice versa." ], "ex": "If BTC keeps bouncing near $60,000 three times, that's support. A daily close at $58,500 breaks it — but if price jumps back above $60,000 the next candle, it was a fakeout.", "quiz": { "q": "Which pattern defines an uptrend?", "o": [ "Lower highs and lower lows", "Flat highs and lows", "Higher highs and higher lows", "Random spikes with no structure" ], "a": 2 }, "link": { "href": "/charts", "label": "Plot Support/Resistance & Pivot Points on the chart" } },
    { "id": "moving-averages", "t": "Moving averages (EMA & SMA)", "mins": 5, "sum": "Smooth out noise, spot trend direction, and golden/death crosses.", "body": [ { "h": "SMA vs EMA vs Hull", "p": "A <b>moving average (MA)</b> is the average price over the last N candles, redrawn each candle to smooth out noise. A <b>Simple MA (SMA)</b> weights every candle equally. An <b>Exponential MA (EMA)</b> weights recent candles more, so it reacts faster to new price. A <b>Hull MA (HMA)</b> is engineered to be even faster and smoother. Faster MAs catch turns sooner but give more false wiggles; slower MAs are steadier but lag more." }, { "h": "Reading direction and dynamic S/R", "p": "Price above a rising MA suggests an uptrend; below a falling MA suggests a downtrend. MAs also act as <b>dynamic support/resistance</b> — in a strong uptrend, pullbacks often bounce off the 50-EMA or 200-EMA. The number (e.g. '200') is how many candles it averages." }, { "h": "Golden cross & death cross", "p": "A <b>golden cross</b> is when a shorter MA (e.g. 50) crosses <i>above</i> a longer MA (e.g. 200) — often read as bullish momentum building. A <b>death cross</b> is the shorter crossing <i>below</i> the longer — read as bearish. Caveat: MAs <i>lag</i> price, so these crosses confirm a move that has already started and can whipsaw (flip back and forth) in sideways markets." } ], "key": [ "MAs smooth price; EMA reacts faster than SMA, Hull faster still.", "Price vs a rising/falling MA gives quick trend context.", "MAs act as dynamic support/resistance during trends.", "Golden/death crosses lag and whipsaw in ranges — they confirm, not predict." ], "ex": "On a daily chart, the 50-day SMA crossing above the 200-day SMA is the classic 'golden cross'. Because both are slow, the signal arrives well after the bottom — useful for trend confirmation, not perfect timing.", "quiz": { "q": "Why does an EMA react faster to price than an SMA of the same length?", "o": [ "It ignores older candles entirely", "It weights recent candles more heavily", "It uses volume instead of price", "It only updates once a day" ], "a": 1 }, "link": { "href": "/charts", "label": "Add EMA, SMA or Hull MA on the chart" } },
    { "id": "rsi", "t": "RSI — momentum & overbought/oversold", "mins": 5, "sum": "A 0–100 momentum gauge: 70 overbought, 30 oversold, watch divergence.", "body": [ { "h": "What RSI measures", "p": "The <b>Relative Strength Index (RSI)</b> is a momentum oscillator that scores recent price changes on a scale of <b>0 to 100</b> (default lookback: 14 candles). It compares the size of recent gains to recent losses — high RSI means gains have dominated, low RSI means losses have. It tells you about <i>momentum and speed</i>, not price level." }, { "h": "The 70 / 30 levels", "p": "<b>Above 70</b> is conventionally called <b>overbought</b> (price has risen fast and may be stretched). <b>Below 30</b> is <b>oversold</b> (fallen fast). Important: overbought does <i>not</i> mean 'sell now'. In a strong uptrend RSI can sit above 70 for a long time while price keeps climbing — so these are alerts to pay attention, not automatic buy/sell triggers." }, { "h": "Divergence and its limits", "p": "<b>Divergence</b> is when price and RSI disagree: price makes a higher high but RSI makes a lower high (<i>bearish divergence</i>), or price makes a lower low but RSI makes a higher low (<i>bullish divergence</i>). This can hint that momentum is fading. But divergence can persist for a long time before price reacts, and it fails often in strong trends — confirm with price action, never trade it alone." } ], "key": [ "RSI is a 0–100 momentum gauge, default length 14.", "Above 70 = overbought, below 30 = oversold — alerts, not signals.", "In strong trends RSI can stay overbought/oversold for a long time.", "Divergence hints at fading momentum but fails often — confirm with price." ], "ex": "RSI above 70 during a powerful rally doesn't mean sell — in a strong uptrend it can hold 70–80 for days while price keeps rising. Shorting purely because 'RSI is overbought' is a classic beginner mistake.", "quiz": { "q": "RSI has been above 70 for several days in a strong uptrend. What's the most accurate read?", "o": [ "It's a guaranteed sell signal", "Price has fallen sharply", "Momentum is strong; overbought can persist in a trend", "RSI is broken and should be ignored" ], "a": 2 }, "link": { "href": "/charts", "label": "Add RSI on the chart" } },
    { "id": "macd", "t": "MACD — momentum & crossovers", "mins": 5, "sum": "MACD line, signal line and histogram — crossovers and the zero line.", "body": [ { "h": "The three parts", "p": "<b>MACD (Moving Average Convergence Divergence)</b> measures the relationship between two EMAs. The <b>MACD line</b> is the 12-period EMA minus the 26-period EMA. The <b>signal line</b> is a 9-period EMA of the MACD line — a smoother version. The <b>histogram</b> is the gap between them (MACD minus signal), drawn as bars; it shows how fast they're converging or diverging." }, { "h": "Crossovers", "p": "A <b>bullish crossover</b> is when the MACD line crosses <i>above</i> the signal line (histogram flips positive) — momentum turning up. A <b>bearish crossover</b> is the MACD line crossing <i>below</i> the signal line. These are the most-watched MACD signals, but because MACD is built from EMAs it <i>lags</i> price and whipsaws in choppy, sideways markets." }, { "h": "The zero line", "p": "When the MACD line is <b>above zero</b>, the fast EMA is above the slow EMA — a broadly bullish backdrop. <b>Below zero</b> is broadly bearish. Many traders treat a crossover that happens on the 'right' side of zero (e.g. a bullish cross while above zero) as higher-quality. Like all indicators, it confirms momentum that's already moving — it doesn't predict reversals on its own." } ], "key": [ "MACD line = 12-EMA − 26-EMA; signal = 9-EMA of MACD; histogram = the gap.", "MACD crossing above signal = bullish; below = bearish.", "Above/below the zero line shows the broader bullish/bearish backdrop.", "MACD lags and whipsaws in ranges — it confirms, it doesn't predict." ], "ex": "The histogram shrinking toward zero while still positive warns that bullish momentum is fading <i>before</i> the actual bearish crossover prints — an early heads-up, not a trade trigger.", "quiz": { "q": "What is the MACD histogram?", "o": [ "The 12-period EMA of price", "Trading volume per candle", "The gap between the MACD line and the signal line", "The RSI plotted as bars" ], "a": 2 }, "link": { "href": "/charts", "label": "Add MACD on the chart" } },
    { "id": "bollinger-bands", "t": "Bollinger Bands — volatility & mean reversion", "mins": 5, "sum": "A middle SMA with bands 2 standard deviations out — squeeze and band rides.", "body": [ { "h": "How the bands are built", "p": "<b>Bollinger Bands</b> are three lines: a <b>middle band</b> (usually a 20-period SMA) plus an <b>upper</b> and <b>lower band</b> set <b>2 standard deviations</b> away from it. Standard deviation is a measure of how spread-out prices are, so the bands automatically <i>widen when volatility rises</i> and <i>narrow when it falls</i>. About 95% of price action tends to fall inside 2-deviation bands." }, { "h": "The squeeze", "p": "When the bands pull in tight, that's a <b>squeeze</b> — volatility is unusually low, often before a big move. A squeeze tells you a breakout may be coming but <i>not which direction</i>. Traders wait for price to break out of the squeeze and confirm direction with other tools rather than guessing." }, { "h": "Touches and band rides", "p": "Price touching the upper band does <i>not</i> automatically mean 'overbought / sell'. In a strong trend price can <b>ride the band</b> — hugging the upper band the whole way up (or lower band down). Mean-reversion (fading touches back to the middle) works better in ranging markets, not trending ones. Bollinger Bands describe volatility; they don't give direction by themselves." } ], "key": [ "Middle = 20-SMA; upper/lower = ±2 standard deviations (volatility-based).", "Bands widen in high volatility, narrow in low volatility.", "A squeeze warns of a coming move but not its direction.", "Price can 'ride the band' in trends — a touch isn't a reversal signal." ], "ex": "In a strong uptrend, price can hug the upper band for many candles. A trader who shorts every upper-band touch expecting mean reversion gets repeatedly stopped out — band rides happen in trends.", "quiz": { "q": "What does a Bollinger Band 'squeeze' (bands narrowing) indicate?", "o": [ "A guaranteed move higher", "Low volatility, often before a breakout — direction unknown", "The trend has permanently ended", "Volume has spiked" ], "a": 1 }, "link": { "href": "/charts", "label": "Add Bollinger Bands on the chart" } },
    { "id": "stochastic", "t": "Stochastic oscillator", "mins": 4, "sum": "%K and %D lines, 80/20 overbought/oversold, best in ranges.", "body": [ { "h": "What it measures", "p": "The <b>Stochastic oscillator</b> shows where the current close sits within the recent high-low range, scaled <b>0 to 100</b>. Near 100 means price is closing near the top of its recent range; near 0 means near the bottom. The idea: in an uptrend prices tend to close near their highs, in a downtrend near their lows." }, { "h": "%K and %D", "p": "The <b>%K line</b> is the raw fast line; the <b>%D line</b> is a short moving average of %K (a smoother, slower line). A <b>bullish crossover</b> is %K crossing above %D; <b>bearish</b> is %K crossing below %D. Crossovers happening in the extreme zones are watched more closely." }, { "h": "80 / 20 and best use", "p": "<b>Above 80</b> is considered overbought, <b>below 20</b> oversold. Stochastic works best in <i>range-bound</i> (sideways) markets, where fading the extremes back toward the middle is reasonable. In strong trends it stays pinned in the extreme zone and gives repeated false reversal signals — the same trap as RSI. Treat extremes as context, not commands." } ], "key": [ "Stochastic measures where the close sits in the recent high-low range (0–100).", "%K is the fast line; %D is a moving average of %K.", "Above 80 = overbought, below 20 = oversold.", "Best in ranges; in strong trends it stays pinned and gives false signals." ], "ex": "In a choppy, sideways market, Stochastic dropping below 20 then crossing back up can flag a bounce. In a strong downtrend, though, it can sit under 20 for ages while price keeps falling.", "quiz": { "q": "In which market condition is the Stochastic oscillator most reliable?", "o": [ "Strong trending markets", "Range-bound (sideways) markets", "Only on weekends", "When volume is zero" ], "a": 1 }, "link": { "href": "/charts", "label": "Add Stochastic on the chart" } },
    { "id": "atr-volatility", "t": "ATR & volatility", "mins": 4, "sum": "Average True Range measures volatility — size stops by it, not direction.", "body": [ { "h": "What ATR measures", "p": "The <b>Average True Range (ATR)</b> measures <i>how much price typically moves</i> per candle over a lookback (default 14). 'True range' is the largest of: this candle's high-minus-low, or the gap from the previous close to this high or low (so it captures gaps). ATR is a pure <b>volatility</b> number — a high ATR means big swings, a low ATR means quiet conditions." }, { "h": "Not a direction signal", "p": "Crucially, ATR says <i>nothing about direction</i>. A rising ATR doesn't mean up or down — only that moves are getting bigger. So you never 'buy because ATR is high'. Its value is in sizing and in setting expectations for how far price normally travels." }, { "h": "Sizing stops with ATR", "p": "Because a fixed dollar stop ignores how volatile the asset is, many traders set stops as a <i>multiple of ATR</i> — e.g. a stop 1.5× or 2× ATR away from entry — so the stop is wide enough to survive normal noise but still defined. In a high-ATR market you'd give the trade more room (and trade smaller size); in a quiet market, tighter. Use a position-size calculator to turn that stop distance into a sane position size." } ], "key": [ "ATR measures average price movement (volatility), default length 14.", "It captures gaps via 'true range' — high-low or distance from prior close.", "ATR has no direction — never use it as a buy/sell signal.", "Common use: set stops a multiple of ATR away and size positions accordingly." ], "ex": "If ATR is $500 on BTC, a 2×ATR stop sits $1,000 from entry — wide enough to avoid getting shaken out by normal noise. Feed that stop distance into a sizer to keep risk per trade constant.", "quiz": { "q": "What does ATR tell you?", "o": [ "Whether price will go up or down", "How much price typically moves (volatility), with no direction", "The exact reversal point", "The volume of each candle" ], "a": 1 }, "link": { "href": "/calculators?c=size", "label": "Size a position by your ATR stop" } },
    { "id": "vwap", "t": "VWAP — the volume-weighted average price", "mins": 4, "sum": "Intraday fair value weighted by volume — a key institutional benchmark.", "body": [ { "h": "What VWAP is", "p": "<b>VWAP (Volume-Weighted Average Price)</b> is the average price over the session, but weighted by <i>how much volume traded at each price</i>. Prices where lots of contracts changed hands count more than thin prints. It's normally calculated <b>intraday</b>, resetting at the start of each session, so it represents the day's volume-weighted 'fair value'." }, { "h": "Why institutions watch it", "p": "Big funds use VWAP as a <b>benchmark</b>: a desk filling a large order tries to buy <i>below</i> VWAP or sell <i>above</i> it to prove they got a good average price. Because so much size references it, VWAP often acts as a magnet and as intraday support/resistance." }, { "h": "How traders read it", "p": "Price <b>above VWAP</b> is often read as intraday bullish (buyers in control), <b>below VWAP</b> as bearish; pullbacks to VWAP in a trend can offer entries. Limitations: VWAP is most meaningful for <i>intraday</i> trading and resets each session, so it's less useful on higher timeframes or thin markets. It's a reference level, not a trade signal by itself." } ], "key": [ "VWAP = average price weighted by volume, usually reset each session.", "It's a fair-value benchmark institutions measure their fills against.", "Above VWAP = intraday bullish bias; below = bearish bias.", "Mainly an intraday tool — it resets daily and isn't a standalone signal." ], "ex": "A fund buying 10,000 contracts wants its average fill below the day's VWAP — that's proof of an efficient entry. Retail traders often watch a pullback to VWAP in an uptrend as a possible bounce zone.", "quiz": { "q": "What makes VWAP different from a simple average price?", "o": [ "It only uses the closing price", "Each price is weighted by the volume traded there", "It ignores volume entirely", "It is calculated once per year" ], "a": 1 }, "link": { "href": "/charts", "label": "Add VWAP on the chart" } },
    { "id": "volume", "t": "Volume — confirming moves", "mins": 4, "sum": "Volume spikes confirm conviction; divergence warns a move is weak.", "body": [ { "h": "What volume is", "p": "<b>Volume</b> is how many units (contracts/coins) traded during a candle, drawn as bars under price. It measures <i>participation</i> — how many people are actually behind a move. Volume on its own has no direction; it's a confirmation tool that adds context to price." }, { "h": "Confirmation", "p": "A breakout or strong candle on <b>high volume</b> shows real conviction — many participants agree, so the move is more likely to stick. The classic rule of thumb: 'volume confirms price'. A rally on rising volume is healthier than a rally on shrinking volume." }, { "h": "Divergence and exhaustion", "p": "When price keeps rising but volume <i>shrinks</i>, that's <b>volume divergence</b> — fewer buyers are chasing, so the move may be running out of fuel. A breakout on <i>low</i> volume is suspect and more prone to being a fakeout. Watch out: a single huge <b>climax</b> spike can also mark exhaustion (the last buyers piling in at the top). Volume is best read alongside price, never alone." } ], "key": [ "Volume measures participation per candle — it has no direction itself.", "High volume on a breakout confirms conviction; low volume is suspect.", "Rising price on falling volume (divergence) warns a move may be weak.", "A climax volume spike can mark exhaustion — read volume with price." ], "ex": "Price breaks resistance on a huge volume bar — strong confirmation the breakout is real. The same break on the thinnest volume in days is far more likely to fail.", "quiz": { "q": "Price is rising but volume is steadily shrinking. What does this suggest?", "o": [ "The move has strong conviction", "Fewer buyers are participating — the move may be weakening", "Volume guarantees a reversal", "Price will definitely keep rising" ], "a": 1 }, "link": { "href": "/charts", "label": "Add Volume on the chart" } },
    { "id": "supertrend-signals", "t": "Supertrend & buy/sell signals", "mins": 4, "sum": "An ATR-based trend follower that flips bias — and why no signal is perfect.", "body": [ { "h": "How Supertrend works", "p": "<b>Supertrend</b> plots a single line that sits below price in an uptrend and above price in a downtrend. It's built from <b>ATR</b> (volatility): the line trails price at an ATR-based distance, so it gives room for normal noise. When price closes through the line, the trend <b>flips</b> and the line jumps to the other side — printing a <b>buy</b> (flip to bullish) or <b>sell</b> (flip to bearish) marker." }, { "h": "What it's good at", "p": "Supertrend shines in <i>trending</i> markets: it keeps you on the right side of a sustained move and visually marks the trailing stop. Because it's ATR-based, it adapts to volatility — widening in wild markets, tightening in calm ones." }, { "h": "Why no signal is perfect", "p": "In <b>choppy, sideways</b> markets Supertrend gets <b>whipsawed</b> — it flips buy/sell repeatedly as price chops across the line, generating a string of small losing signals. Like every indicator it's based on <i>past</i> price, so flips arrive after the move starts. Treat 'buy/sell' markers as a trend bias and an exit guide, not a guaranteed entry — confirm with the bigger trend and a real risk plan." } ], "key": [ "Supertrend is an ATR-based trend follower that flips bias when price crosses it.", "It works well in trends and doubles as a visual trailing stop.", "It whipsaws badly in sideways markets, firing false signals.", "Signals lag (built on past price) — use them as bias, not a guarantee." ], "ex": "In a clean uptrend Supertrend trails below price the whole way, keeping you long until a real reversal flips it to sell. In a tight range it can flip buy/sell five times in a row, each a small loss.", "quiz": { "q": "When is Supertrend most likely to give false signals?", "o": [ "In strong, sustained trends", "In choppy, sideways markets", "When volume is high", "Only on daily charts" ], "a": 1 }, "link": { "href": "/charts", "label": "Turn on Buy/Sell (Supertrend) signals" } },
    { "id": "confluence", "t": "Confluence — combining indicators", "mins": 5, "sum": "Stack trend + momentum + level for agreement; avoid over-stacking.", "body": [ { "h": "Why one indicator isn't enough", "p": "Every indicator has a blind spot: RSI gives false 'overbought' in trends, MACD whipsaws in ranges, Bollinger touches lie during band rides. <b>Confluence</b> means looking for <i>several independent tools agreeing</i> at the same spot — when they line up, the read is sturdier than any single signal." }, { "h": "Align different types", "p": "The trick is to combine tools that measure <i>different</i> things, not duplicates. A solid stack mixes a <b>trend</b> tool (moving averages / Supertrend), a <b>momentum</b> tool (RSI / MACD / Stochastic), and a <b>level</b> (support/resistance, pivots, or VWAP). Example confluence: price pulling back to support, inside an uptrend (price above the 200-EMA), with RSI turning up from oversold and volume picking up." }, { "h": "Avoid over-stacking", "p": "More indicators is <i>not</i> better. Piling on five momentum oscillators that all say the same thing creates a false sense of confidence (they're redundant) and 'analysis paralysis' when they disagree. Keep it to a few complementary tools, always define your <b>risk</b> first, and remember: indicators are decision <i>aids</i>, not a crystal ball. None of this is financial advice — they describe probabilities, never certainties." } ], "key": [ "Confluence = several independent tools agreeing at one spot — sturdier than one.", "Combine different types: trend + momentum + a level (not duplicates).", "Over-stacking redundant indicators causes false confidence and paralysis.", "Indicators are aids that describe probabilities — define risk first." ], "ex": "Higher-confidence long: price holds support <i>and</i> sits above the 200-EMA (trend) <i>and</i> RSI turns up from oversold (momentum) <i>and</i> volume rises (participation). Four different tools, one story.", "quiz": { "q": "What's the best way to combine indicators for confluence?", "o": [ "Stack five momentum oscillators that all measure the same thing", "Use one indicator and ignore the rest", "Combine different types — trend, momentum and a level", "Pick whichever currently agrees with your hope" ], "a": 2 }, "link": { "href": "/charts", "label": "Build your own confluence on the chart workspace" } }
  ]
};

const RISK = {
  "id": "risk",
  "name": "Risk & Psychology",
  "icon": "🛡️",
  "blurb": "Survive first, profit second — sizing, stops, risk of ruin and the mental game.",
  "level": "advanced",
  "lessons": [
    { "id": "why-risk-beats-being-right", "t": "Why risk management beats being right", "mins": 4, "sum": "You can win at 40% accuracy and still grow — one blown account ends the game.", "body": [ { "h": "Being right is overrated", "p": "Most new traders chase a high <b>win rate</b>. But your win rate barely matters on its own. What matters is how much you make when right versus how much you lose when wrong. A trader who wins only <b>40%</b> of the time can still grow an account steadily — if winners are bigger than losers. A trader who wins <b>70%</b> of the time can go broke if a few losses are huge." }, { "h": "The math of survival", "p": "The killer is the <b>drawdown</b>. Losing 50% of your account doesn't mean you need a 50% gain to recover — you need <b>100%</b>. Lose 80% and you need a <b>400%</b> gain just to get back to even. <ul><li>Down 10% → need +11% to recover</li><li>Down 50% → need +100%</li><li>Down 80% → need +400%</li></ul> This is why a single oversized, unstopped trade can permanently end you, even if your strategy was 'right' most of the time." }, { "h": "Stay in the game", "p": "Trading is not about being right on the next trade. It's about <b>surviving long enough</b> for your edge to play out over hundreds of trades. You cannot compound an account that hits zero. <i>Protecting capital is the strategy</i> — everything else is secondary." } ], "key": [ "Win rate alone tells you nothing — size of wins vs losses decides the outcome", "Drawdowns hurt asymmetrically: down 50% needs +100% to recover, down 80% needs +400%", "One oversized loss can end the game no matter how often you were right" ], "ex": "Trader A wins 40% of trades but makes 3R on wins and loses 1R on losses. Over 100 trades: 40 wins × 3R = +120R, 60 losses × 1R = -60R → net +60R. Trader B wins 70% but loses 5R on the 30% that go wrong: 70 × 1R = +70R, 30 × 5R = -150R → net -80R. Trader B was 'right' more often and still lost.", "quiz": { "q": "After a 50% drawdown, what gain do you need just to get back to break-even?", "o": [ "50%", "75%", "100%", "150%" ], "a": 2 } },
    { "id": "one-percent-rule", "t": "The 1% rule — never risk more than you can lose", "mins": 4, "sum": "Risk a small fixed % of your account per trade so no single loss can hurt you.", "body": [ { "h": "Cap the damage per trade", "p": "The <b>1% rule</b> means you never risk more than <b>1%</b> of your account on a single trade. 'Risk' here is the amount you lose if your stop is hit — <i>not</i> your position size or margin. On a $10,000 account, 1% risk = <b>$100</b> max loss per trade. Many traders use 0.5% to 2%; 1% is a sane default." }, { "h": "Why a fixed percentage", "p": "Using a <b>percentage</b> instead of a fixed dollar amount means your risk shrinks automatically when you're losing and grows as you win. After a 10-trade losing streak at 1% each, you've lost roughly <b>10%</b> — annoying, but fully recoverable. At 10% risk per trade, that same streak nearly wipes you out. <ul><li>1% risk × 10 losses ≈ -9.6%</li><li>10% risk × 10 losses ≈ -65%</li></ul>" }, { "h": "It's a survival floor, not a target", "p": "The 1% rule doesn't make you money — it keeps you <b>alive</b> through inevitable losing streaks so your edge has time to work. Combine it with proper <code>position sizing</code> so that the distance to your stop, not a round number of contracts, decides how big you trade." } ], "key": [ "Risk = what you lose if the stop hits, not your margin or notional size", "1% of a $10,000 account is $100 max loss per trade", "Percentage risk auto-scales down in drawdowns, protecting you from streaks" ], "ex": "Account = $10,000, risk 1% = $100 per trade. Suffer 6 losses in a row: -$100 × 6 = -$600, account now $9,400 (down 6%). Easily recoverable. Had you risked 15% ($1,500) per trade, 6 losses = roughly -$6,000, leaving $4,000 (down 60%) — needing a +150% gain to recover.", "quiz": { "q": "On a $20,000 account using the 1% rule, what is your maximum loss on a single trade?", "o": [ "$20", "$200", "$1,000", "$2,000" ], "a": 1 }, "link": { "href": "/calculators?c=size", "label": "Size a trade to your 1% risk" } },
    { "id": "stop-loss-take-profit", "t": "Stop-loss & take-profit", "mins": 5, "sum": "Decide your exits before you enter — where the stop goes and when to take profit.", "body": [ { "h": "Exits are decided before entry", "p": "A <b>stop-loss</b> is the price where you admit the trade is wrong and get out. A <b>take-profit</b> is where you bank gains. Both must be set <i>before</i> you enter, while you're calm and objective. Once you're in a losing trade, your brain will invent reasons to move the stop — that's how small losses become account-killers." }, { "h": "Where to place the stop", "p": "Place stops at a level that <b>invalidates your trade idea</b>, not at a random dollar amount. Two common methods: <ul><li><b>Structure</b>: just beyond a recent swing high/low or support/resistance — if price breaks it, your setup is wrong.</li><li><b>ATR</b>: a multiple of Average True Range (e.g. 1.5× ATR) to give the trade room to breathe through normal noise.</li></ul> Never set a stop so tight that ordinary volatility takes you out, nor so wide that hitting it blows your risk budget." }, { "h": "Moving to break-even", "p": "Once a trade moves meaningfully in your favor, you can move the stop to your <b>entry price</b> (break-even) so a winner can't turn into a loser. Do this at a logical level — not the instant you're up a few dollars, or normal pullbacks will stop you out before the move develops. <i>Move stops to protect, never to give a losing trade 'more room'.</i>" } ], "key": [ "Set both stop and take-profit before entering, while you're objective", "Place stops where your idea is proven wrong (structure or ATR), not at a round number", "Move stops only to lock in safety — never widen a stop on a losing trade" ], "ex": "Long at $100. Recent swing low is $96, so structure stop = $95.50 (just below it). Risk = $4.50/unit. Targeting the next resistance at $113.50 gives reward = $13.50/unit, a 3:1 reward-to-risk. After price reaches $109, move stop to $100 (break-even): now the worst case is a scratch, not a loss.", "quiz": { "q": "What is the best reason to move a stop-loss to break-even?", "o": [ "To give a losing trade more room", "To lock in a no-loss outcome after the trade moves in your favor", "Because price dipped slightly against you", "To avoid ever taking a loss" ], "a": 1 }, "link": { "href": "/calculators?c=tp", "label": "Plan your stop & take-profit levels" } },
    { "id": "position-sizing-math", "t": "Position sizing math", "mins": 5, "sum": "Turn your risk % and stop distance into the exact position size — no guessing.", "body": [ { "h": "The core formula", "p": "Position size is not a feeling — it's arithmetic. The formula is: <code>Position size = (Account × Risk %) ÷ Stop distance</code>. First find your <b>risk amount</b> in dollars (account × risk %), then divide by how far your stop is from entry. This gives the number of units/contracts so that hitting your stop loses exactly your intended risk." }, { "h": "Stop distance drives size", "p": "Here's the part most people get backwards: a <b>wider stop means a smaller position</b>, and a tighter stop means a larger one — for the <i>same</i> dollar risk. Your risk in dollars stays fixed at, say, $100; the stop distance is what flexes your size. <ul><li>Tight stop ($1 away) → larger position</li><li>Wide stop ($5 away) → smaller position</li></ul> Both lose the same $100 if stopped out. Sizing by risk, never by 'how many contracts can I afford', is the whole game." }, { "h": "Leverage is a side effect", "p": "Notice the formula never mentions leverage. You size the position from risk first; the leverage is just whatever the resulting position requires in margin. <i>Risk decides size — leverage is the leftover.</i>" } ], "key": [ "Position size = (Account × Risk %) ÷ Stop distance", "Same dollar risk: wider stop = smaller size, tighter stop = bigger size", "Size from risk first; leverage is just the consequence, not the input" ], "ex": "Account = $5,000, risk 1% = $50. Long entry at $200 with a stop at $190 → stop distance = $10. Position size = $50 ÷ $10 = 5 units (notional $1,000). If the stop hits, you lose 5 × $10 = $50, exactly 1%. Tighten the stop to $195 ($5 distance): size = $50 ÷ $5 = 10 units — bigger position, same $50 risk.", "quiz": { "q": "Account $10,000, risk 1% ($100), entry $50, stop $48 ($2 away). What's the position size?", "o": [ "20 units", "50 units", "100 units", "200 units" ], "a": 1 }, "link": { "href": "/calculators?c=size", "label": "Calculate your exact position size" } },
    { "id": "risk-of-ruin-expectancy", "t": "Risk of ruin & expectancy", "mins": 6, "sum": "How win rate, R:R and risk % decide whether you survive — and why greed guarantees ruin.", "body": [ { "h": "Expectancy: does your edge make money?", "p": "<b>Expectancy</b> is your average profit per trade in R (risk units). Formula: <code>Expectancy = (Win% × Avg win in R) − (Loss% × Avg loss in R)</code>. If it's <b>positive</b>, you have an edge; if it's zero or negative, no amount of position sizing saves you — you're just choosing how fast to lose. Positive expectancy is the prerequisite for everything else." }, { "h": "Risk of ruin: will you survive the edge?", "p": "Even with positive expectancy, randomness produces losing streaks. <b>Risk of ruin</b> is the probability you hit zero (or a stop-out threshold) before your edge pays off. Three things drive it: <ul><li><b>Win rate</b> — higher is safer</li><li><b>Reward-to-risk</b> — bigger winners cushion streaks</li><li><b>Risk per trade</b> — the biggest lever, and the one you fully control</li></ul> A positive-expectancy system can <i>still</i> ruin you if you risk too much per trade." }, { "h": "Why high leverage + big risk = near-certain ruin", "p": "Cranking risk per trade does not scale your returns linearly — it scales your <b>ruin probability</b> toward 100%. Risk 2% per trade with a decent edge and risk of ruin can be a fraction of a percent. Risk 25% per trade and even a <i>winning</i> system gets wiped out by a normal 4-5 trade losing streak — because 4 losses at 25% leaves you needing a +144% gain to recover. <b>Over-betting turns an edge into a slot machine.</b>" } ], "key": [ "Expectancy = (Win% × Avg win R) − (Loss% × Avg loss R); it must be positive to have an edge", "Risk of ruin rises fast with risk-per-trade — it's the lever you control", "A positive-edge system still goes broke if you over-bet each trade" ], "ex": "System: 45% win rate, winners = 2R, losers = 1R. Expectancy = (0.45 × 2) − (0.55 × 1) = 0.90 − 0.55 = +0.35R per trade — a real edge. But risk 25% per trade and a 5-loss streak (very common at 45% win rate) costs ~76% of the account, needing a +317% recovery. Same edge at 1% risk: that streak costs ~5%, fully survivable. The edge didn't change — the bet size decided survival.", "quiz": { "q": "A system with positive expectancy can still blow up the account if you...", "o": [ "Use a stop-loss on every trade", "Risk too large a percentage on each trade", "Take profits at a 2:1 reward-to-risk", "Trade fewer times per week" ], "a": 1 }, "link": { "href": "/risk-of-ruin-calculator/", "label": "Estimate your risk of ruin" } },
    { "id": "leverage-discipline", "t": "Leverage discipline", "mins": 5, "sum": "Leverage isn't more buying power — it's a tighter liquidation. Size by risk, not max lev.", "body": [ { "h": "What leverage actually is", "p": "Traders treat <b>leverage</b> as 'more buying power'. It isn't. Leverage doesn't increase your edge or your expected return — it only moves your <b>liquidation price closer</b> to your entry. At 10× a ~10% adverse move liquidates you; at 50× roughly a <b>2%</b> move does; at 100× barely <b>1%</b>. Higher leverage = less room before the exchange force-closes you at a total loss on that margin." }, { "h": "Liquidation vs your stop", "p": "Your real risk control is your <b>stop-loss</b>, which should always trigger <i>before</i> liquidation. If high leverage puts your liquidation price inside the normal noise of the market, you'll get liquidated even when your trade idea was fine. The goal is to keep liquidation far away — so your planned stop, not a violent wick, decides your exit." }, { "h": "Size by risk, not by max leverage", "p": "The discipline: decide your position size from <b>risk and stop distance</b> first (previous lesson), then use only as much leverage as that position happens to require. <i>'Max leverage available' is not a target — it's a trap.</i> Two accounts with the same position can have wildly different leverage; the one keeping liquidation far from price survives." } ], "key": [ "Leverage moves your liquidation price closer — it does not raise your edge", "Rough liquidation distance: 10× ≈ 10%, 50× ≈ 2%, 100× ≈ 1% adverse move", "Set size from risk and stop first; leverage is the leftover, never the goal" ], "ex": "You want to risk $100 on a trade with a $200 entry and a $190 stop (5% away). Correct size is fixed by risk: 10 units ($2,000 notional). On a $1,000 margin allocation that's only 2× leverage and your liquidation sits far below your $190 stop. Crank to 50× on the same margin and liquidation lands around $196 — above your stop — so noise liquidates you before your idea is even proven wrong.", "quiz": { "q": "Increasing leverage from 10× to 50× primarily does what?", "o": [ "Increases your expected profit per trade", "Moves your liquidation price much closer to entry", "Reduces your risk of ruin", "Improves your win rate" ], "a": 1 } },
    { "id": "trading-psychology", "t": "Trading psychology", "mins": 5, "sum": "Fear, greed, FOMO, revenge and tilt wreck accounts — pre-set rules beat in-the-moment emotion.", "body": [ { "h": "The four account-killers", "p": "Your strategy isn't usually what blows the account — your emotions overriding it are. The usual suspects: <ul><li><b>Fear</b>: cutting winners early, skipping valid setups after a loss.</li><li><b>Greed</b>: oversizing, moving take-profits further out, refusing to bank gains.</li><li><b>FOMO</b>: chasing a candle that already ran, entering with no plan.</li><li><b>Revenge trading</b>: forcing trades to 'win back' a loss — usually bigger and dumber.</li></ul>" }, { "h": "Tilt is real", "p": "<b>Tilt</b> is the emotional spiral after a loss or a hot streak where you stop following your rules. It's the single most expensive state a trader can be in: one tilted session can erase weeks of disciplined gains. The fix isn't 'try to feel calmer' — it's a hard rule like <i>stop trading for the day after two losses or a daily loss limit</i>, decided in advance and obeyed mechanically." }, { "h": "Rules beat emotions", "p": "You will not out-discipline your brain in the heat of a trade — adrenaline wins every time. The only reliable defense is <b>pre-committed rules</b>: fixed risk per trade, fixed entry/exit criteria, a daily loss limit, and a 'walk away' trigger. Automate what you can (stop orders, alerts) so the decision is already made before emotion shows up." } ], "key": [ "Most blown accounts come from emotion overriding the plan, not a bad strategy", "Revenge trading and tilt cause the biggest, fastest losses — set a daily loss limit", "You can't out-discipline adrenaline; pre-commit to rules and automate exits" ], "ex": "Trader takes two quick losses (-2% total) and feels furious. On tilt, they double size to 'win it back', skip the stop, and the trade runs -15%. A simple pre-set rule — 'after 2 losses, stop trading until tomorrow' — would have capped the day at -2% instead of -17%. The rule, not willpower, saved the account.", "quiz": { "q": "What's the most reliable defense against revenge trading and tilt?", "o": [ "Trying harder to stay calm during the trade", "Pre-committed rules like a daily loss limit and a walk-away trigger", "Increasing position size to recover losses faster", "Removing your stop-loss to give trades room" ], "a": 1 } },
    { "id": "trading-plan-journal", "t": "Build a trading plan & journal", "mins": 5, "sum": "Write your entry/exit/risk rules down, then journal and review every trade to improve.", "body": [ { "h": "If it's not written, it's not a plan", "p": "A <b>trading plan</b> is a written document, not a vibe. At minimum it states: <ul><li><b>Entry rules</b> — the exact conditions that justify a trade.</li><li><b>Exit rules</b> — where the stop and take-profit go and why.</li><li><b>Risk rules</b> — % risked per trade, max open trades, daily loss limit.</li></ul> Writing it down forces specifics and gives you something to be accountable to. If you can't write the rule, you don't actually have one." }, { "h": "Journal every trade", "p": "A <b>trading journal</b> records each trade: entry, exit, size, risk, the reason you took it, and whether you followed your plan. The most important column isn't profit — it's <b>'did I follow my rules?'</b> A losing trade taken by the plan is a <i>good</i> trade; a winning trade taken on impulse is a bad habit that will eventually cost you." }, { "h": "Review to find the leak", "p": "Edge comes from <b>review</b>. Every week, look for patterns: which setups actually pay, what time of day you tilt, whether your rule-breaks cluster around revenge trades. You can't fix what you don't measure. Over dozens of logged trades the data — not your gut — tells you what to keep and what to cut." } ], "key": [ "A real plan is written: entry rules, exit rules, and risk rules", "Journal every trade and grade it on 'did I follow my plan?', not just P&L", "Weekly review turns logged trades into the patterns you fix to improve" ], "ex": "After 50 logged trades, review reveals your plan-following trades net +0.4R each, but your 9 impulse 'FOMO' entries net -1.8R each and account for nearly all your losses. The fix isn't a new strategy — it's cutting the unplanned trades. Without the journal, you'd never have seen that one leak was sinking the whole account.", "quiz": { "q": "In a trading journal, the single most valuable thing to track is:", "o": [ "The total profit on each trade", "Whether you followed your written plan on each trade", "How you felt about the market that day", "The exchange you used" ], "a": 1 }, "link": { "href": "/trading-journal/", "label": "Start journaling your trades" } }
  ]
};

const GLOSSARY = [
  {"t":"Spot","d":"Buying or selling the actual cryptocurrency for immediate delivery at the current price. You own the coin outright, with no leverage or expiry.","cat":"Basics"},
  {"t":"Futures","d":"A contract to buy or sell an asset at a set price on a future date. In crypto, used to speculate on price with leverage without owning the coin.","cat":"Basics"},
  {"t":"Perpetual swap","d":"A futures contract with <b>no expiry date</b>. It tracks spot price via a <i>funding rate</i> and is the most traded crypto derivative.","cat":"Basics"},
  {"t":"Long","d":"A position that profits when price <b>rises</b>. You buy expecting to sell higher later.","cat":"Basics"},
  {"t":"Short","d":"A position that profits when price <b>falls</b>. You sell first (borrowed) hoping to buy back cheaper.","cat":"Basics"},
  {"t":"Position","d":"Your current open trade in a market — either long or short — including its size, entry price, and unrealized profit or loss.","cat":"Basics"},
  {"t":"Notional","d":"The total value of your position (size × price), including borrowed funds. With leverage it's far larger than your margin.","cat":"Basics"},
  {"t":"Margin","d":"The collateral you deposit to open and hold a leveraged position. It's a fraction of the position's notional value.","cat":"Basics"},
  {"t":"Collateral","d":"Assets (like USDT or BTC) you lock up to back a leveraged trade. If losses erode it past a threshold, you get liquidated.","cat":"Basics"},
  {"t":"Maker","d":"A trader who adds liquidity by placing a <i>limit order</i> that rests on the book. Usually pays lower fees.","cat":"Basics"},
  {"t":"Taker","d":"A trader who removes liquidity by filling an existing order immediately (e.g. a market order). Usually pays higher fees.","cat":"Basics"},
  {"t":"Slippage","d":"The difference between your expected fill price and the actual price you get, common in fast or thin markets.","cat":"Basics"},
  {"t":"Bid/Ask","d":"The <b>bid</b> is the highest price buyers will pay; the <b>ask</b> is the lowest price sellers will accept.","cat":"Basics"},
  {"t":"Spread","d":"The gap between the bid and ask price. A tight spread means a liquid market; a wide spread means higher trading cost.","cat":"Basics"},
  {"t":"Order book","d":"A live list of all open buy and sell orders for a market, showing price levels and the size available at each.","cat":"Basics"},
  {"t":"Mark price","d":"A fair reference price (based on the index plus funding) used to calculate unrealized P&L and liquidations, preventing manipulation.","cat":"Basics"},
  {"t":"Index price","d":"An average spot price of an asset across major exchanges. It anchors the mark price and funding rate.","cat":"Basics"},
  {"t":"Unrealized P&L","d":"The profit or loss on an open position at current prices. It isn't locked in until you close the trade.","cat":"Basics"},
  {"t":"Realized P&L","d":"The actual profit or loss <b>booked</b> once you close a position. Unlike unrealized P&L, it can't change.","cat":"Basics"},
  {"t":"Market order","d":"An order to buy or sell <b>immediately</b> at the best available price. Fast fill, but you pay the spread and risk slippage.","cat":"Orders"},
  {"t":"Limit order","d":"An order to buy or sell at a <b>specific price or better</b>. It only fills if the market reaches your price, giving you control but no guarantee.","cat":"Orders"},
  {"t":"Stop-loss","d":"An order that closes your position once price hits a set level, <b>capping your loss</b>. Essential risk management.","cat":"Orders"},
  {"t":"Take-profit","d":"An order that closes your position once price reaches a target, <b>locking in gains</b> automatically.","cat":"Orders"},
  {"t":"Stop-limit","d":"A stop order that, once triggered, places a <i>limit order</i> instead of a market order — avoiding bad fills but risking no fill.","cat":"Orders"},
  {"t":"Trailing stop","d":"A stop-loss that moves with the price in your favor by a set distance, locking in profit while letting winners run.","cat":"Orders"},
  {"t":"Reduce-only","d":"An order setting that can only <b>shrink or close</b> a position, never open or flip one. Prevents accidental over-exposure.","cat":"Orders"},
  {"t":"Post-only","d":"A limit order that's canceled if it would fill immediately, ensuring you stay a <i>maker</i> and earn lower fees.","cat":"Orders"},
  {"t":"OCO","d":"<b>One-Cancels-the-Other</b>: two linked orders (e.g. take-profit and stop-loss) where filling one automatically cancels the other.","cat":"Orders"},
  {"t":"Leverage","d":"Borrowed funds that multiply your position size. <b>10x</b> leverage means $100 controls a $1,000 position — amplifying gains <i>and</i> losses.","cat":"Leverage"},
  {"t":"Cross margin","d":"A mode where your <b>entire account balance</b> backs all positions, sharing margin to avoid liquidation but risking the whole balance.","cat":"Leverage"},
  {"t":"Isolated margin","d":"A mode where only the margin assigned to a position can be lost. It caps risk per trade but liquidates faster.","cat":"Leverage"},
  {"t":"Initial margin","d":"The minimum collateral required to <b>open</b> a leveraged position, set by your chosen leverage.","cat":"Leverage"},
  {"t":"Maintenance margin","d":"The minimum collateral needed to <b>keep</b> a position open. Drop below it and you get liquidated.","cat":"Leverage"},
  {"t":"Liquidation","d":"The forced closing of your position when losses shrink your margin below the maintenance level, so the exchange isn't left at risk.","cat":"Leverage"},
  {"t":"Liquidation price","d":"The price at which your position will be automatically liquidated. Higher leverage moves it closer to your entry.","cat":"Leverage"},
  {"t":"ADL","d":"<b>Auto-Deleveraging</b>: when a liquidation can't be filled, the exchange force-closes opposing profitable traders' positions to cover the loss.","cat":"Leverage"},
  {"t":"Funding rate","d":"Periodic payments between longs and shorts on perpetuals that keep the contract price near spot. Positive means longs pay shorts.","cat":"Leverage"},
  {"t":"Open interest","d":"The total number of outstanding futures contracts not yet closed. Rising OI signals new money entering the market.","cat":"Leverage"},
  {"t":"Margin call","d":"A warning that your collateral is running low and you must add funds or reduce risk to avoid liquidation.","cat":"Risk"},
  {"t":"RSI","d":"<b>Relative Strength Index</b>: a 0–100 momentum gauge. Above 70 suggests overbought, below 30 oversold.","cat":"Indicators"},
  {"t":"MACD","d":"<b>Moving Average Convergence Divergence</b>: a momentum tool comparing two EMAs. Crossovers can signal trend shifts.","cat":"Indicators"},
  {"t":"EMA","d":"<b>Exponential Moving Average</b>: a moving average that weights recent prices more heavily, reacting faster than the SMA.","cat":"Indicators"},
  {"t":"SMA","d":"<b>Simple Moving Average</b>: the average closing price over a set number of periods, smoothing out noise to show trend direction.","cat":"Indicators"},
  {"t":"Bollinger Bands","d":"A band of two lines plotted a set number of standard deviations from a moving average. Widening bands signal rising volatility.","cat":"Indicators"},
  {"t":"VWAP","d":"<b>Volume-Weighted Average Price</b>: the average price weighted by volume over a session. A key intraday fair-value benchmark.","cat":"Indicators"},
  {"t":"ATR","d":"<b>Average True Range</b>: a measure of how much an asset moves on average per period, used to gauge volatility and size stops.","cat":"Indicators"},
  {"t":"Stochastic","d":"A momentum oscillator comparing a close to its recent high-low range, scaled 0–100, to spot overbought/oversold conditions.","cat":"Indicators"},
  {"t":"Support","d":"A price level where buying tends to halt a decline. Price often bounces here until it eventually breaks.","cat":"Indicators"},
  {"t":"Resistance","d":"A price level where selling tends to halt a rise. Price often stalls here until it eventually breaks through.","cat":"Indicators"},
  {"t":"Divergence","d":"When price and an indicator (like RSI) move in <b>opposite directions</b>, often hinting that the current trend is weakening.","cat":"Indicators"},
  {"t":"Candlestick","d":"A chart bar showing open, high, low, and close for a period. Body and wicks reveal momentum and battles between buyers and sellers.","cat":"Indicators"},
  {"t":"Breakout","d":"When price moves decisively beyond a support or resistance level, often sparking a strong follow-through move.","cat":"Indicators"},
  {"t":"Risk-reward ratio","d":"The size of your potential loss versus potential gain on a trade. A <b>1:3</b> ratio risks $1 to make $3.","cat":"Risk"},
  {"t":"Drawdown","d":"The drop from a peak in your account balance to a trough, measuring how much you've lost from a high point.","cat":"Risk"},
  {"t":"Risk of ruin","d":"The probability of losing enough capital that you can no longer trade. Higher risk per trade sharply raises it.","cat":"Risk"},
  {"t":"Position sizing","d":"Deciding how much capital to put into a trade, usually risking a small fixed % of your account to survive losing streaks.","cat":"Risk"},
  {"t":"Win rate","d":"The percentage of your trades that are profitable. A high win rate alone doesn't guarantee profit without good risk-reward.","cat":"Risk"},
  {"t":"Expectancy","d":"The average profit or loss you can expect per trade over time, combining win rate and average win/loss size.","cat":"Risk"},
  {"t":"R-multiple","d":"A trade's profit or loss expressed in units of the amount you risked (R). A +3R trade made three times what you risked.","cat":"Risk"},
  {"t":"Hedge","d":"Opening an offsetting position to reduce risk — e.g. shorting futures to protect spot holdings from a drop.","cat":"Risk"},
  {"t":"Bull market","d":"A sustained period of <b>rising prices</b> and optimism. Traders favor longs and dips tend to get bought.","cat":"Market"},
  {"t":"Bear market","d":"A sustained period of <b>falling prices</b> and pessimism. Rallies tend to get sold and shorts are favored.","cat":"Market"},
  {"t":"Volatility","d":"How much and how fast a price swings. High volatility means bigger moves — more opportunity and more risk.","cat":"Market"},
  {"t":"Volume","d":"The amount of an asset traded over a period. High volume confirms the strength behind a price move.","cat":"Market"},
  {"t":"Long/short ratio","d":"The proportion of traders positioned long versus short. An extreme reading can hint at crowded, contrarian setups.","cat":"Market"},
  {"t":"Basis","d":"The difference between a futures price and the spot price. It reflects market sentiment and the cost of carry.","cat":"Market"},
  {"t":"Contango/backwardation","d":"<b>Contango</b> is when futures trade above spot; <b>backwardation</b> is when they trade below — signaling market expectations.","cat":"Market"}
];

module.exports = { ADV_TRACKS: [FUNDAMENTALS, INDICATORS, RISK], GLOSSARY };
